// Envelope time tables fitted to measurements, carried over from the sample-engine fork
// (tables.cpp is generated by fit_eg.py in oscairn/measurement). Times are in seconds,
// independent of the sample rate.

#pragma once

namespace pcm {
namespace laws {
namespace tables {

extern const float attackSeconds[128];
extern const float decaySecondsPer60dB[128];
extern const float releaseSecondsPer60dB[128];
extern const float releaseRampSeconds[32];

} // namespace tables
} // namespace laws
} // namespace pcm
